import React from "react";
import { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { FaCog, FaImage, FaStar, FaTrash } from 'react-icons/fa';
import {
  DEFAULT_IMAGE_SETTINGS,
  IMAGE_POSITIONS,
  IMAGE_REPEATS,
  IMAGE_SIZES,
} from '../types';
import type { DeviceId, ImageSettings, ImageSlotSettings, MockupData } from '../types';
import type { IconKey } from '../lib/viewModel';
import type { MockupView } from '../lib/viewModel';

/**
 * Background photo layer with a brand-gradient fallback underneath.
 *
 * Loading CORS-first matters: the PNG exporter can only inline a photo it is
 * allowed to read. But plenty of hosts serve images without CORS headers, and
 * a `crossOrigin` request to one of those fails outright — which would leave
 * the rep staring at an empty hero. So we try CORS, fall back to a plain load
 * so the preview is always right, and fall back again to the gradient if the
 * URL is simply broken.
 */
/**
 * Crop settings for the photo slots, published once per template render so
 * <Photo> can look up its own slot without every call site threading props
 * through. Absent provider (or absent slot) means "defaults", which is
 * exactly how every pre-MMX-007 export behaves.
 */
interface ImageContextValue {
  settings: Record<string, ImageSlotSettings>;
  device: DeviceId;
  /**
   * Present only in the builder. When set, every photo container becomes a
   * drop target with its own controls — which is what MMX-007 asked for:
   * drop straight onto the image container you can see.
   */
  onImage?: (slot: string, dataUrl: string) => void;
  onSettings?: (slot: string, value: ImageSlotSettings) => void;
}

const ImageSettingsContext = createContext<ImageContextValue>({
  settings: {},
  device: 'desktop',
});

export function ImageSettingsProvider({
  data,
  device,
  onImage,
  onSettings,
  children,
}: {
  data: MockupData;
  device: DeviceId;
  onImage?: (slot: string, dataUrl: string) => void;
  onSettings?: (slot: string, value: ImageSlotSettings) => void;
  children: React.ReactNode;
}) {
  // Each template publishes its own settings, which would otherwise shadow the
  // builder's provider and silently drop the edit callbacks with it. Inherit
  // whatever an outer provider already supplied.
  const outer = useContext(ImageSettingsContext);
  const image = onImage ?? outer.onImage;
  const setting = onSettings ?? outer.onSettings;

  const value = useMemo(
    () => ({ settings: data.imageSettings || {}, device, onImage: image, onSettings: setting }),
    [data.imageSettings, device, image, setting],
  );
  return <ImageSettingsContext.Provider value={value}>{children}</ImageSettingsContext.Provider>;
}

/** The settings in force for one slot on the device currently being rendered. */
export function useSlotSettings(slot?: string): ImageSettings {
  const { settings, device } = useContext(ImageSettingsContext);
  if (!slot) return DEFAULT_IMAGE_SETTINGS;
  const entry = settings[slot];
  if (!entry) return DEFAULT_IMAGE_SETTINGS;
  return entry[device] || DEFAULT_IMAGE_SETTINGS;
}

/**
 * One photo in one slot.
 *
 * `background-size` and `background-position` map cleanly onto an <img> via
 * object-fit/object-position, which keeps the CORS retry below working and
 * leaves the DOM identical for every slot still on defaults. `repeat` has no
 * <img> equivalent, so that one case — and only that one — renders as a
 * background layer instead.
 */
export function Photo({ src, slot }: { src?: string; slot?: string }) {
  const [useCors, setUseCors] = useState(true);
  const [failed, setFailed] = useState(false);
  const { settings: allSettings, device } = useContext(ImageSettingsContext);
  const { site } = useSite();

  const configured = slot ? allSettings[slot] : undefined;
  const settings = configured ? configured[device] || DEFAULT_IMAGE_SETTINGS : DEFAULT_IMAGE_SETTINGS;

  useEffect(() => {
    setUseCors(true);
    setFailed(false);
  }, [src]);

  if (!src || failed) {
    return (
      <EditableSlot slot={slot}>
        <div className="mk-photo" />
      </EditableSlot>
    );
  }

  // In the exported WEBSITE the two device configurations have to coexist in
  // one document, so the styling is left to a generated stylesheet with real
  // media queries (the same approach MMX-006 uses for data-device). Here we
  // only mark the slot. Inline styles would outrank that stylesheet and pin
  // the site to its desktop crop.
  const hook = site && configured ? { 'data-slot': slot } : {};

  if (settings.repeat === 'repeat' && !site) {
    return (
      <div
        className="mk-photo"
        style={{
          backgroundImage: `url("${src}")`,
          backgroundSize: settings.size,
          backgroundPosition: settings.position,
          backgroundRepeat: 'repeat',
        }}
      />
    );
  }

  // object-fit has no 'auto'; the equivalent is to not scale at all.
  const fit: 'none' | 'cover' | 'contain' = settings.size === 'auto' ? 'none' : settings.size;
  const isDefault =
    settings.size === DEFAULT_IMAGE_SETTINGS.size &&
    settings.position === DEFAULT_IMAGE_SETTINGS.position;
  const inline = site || isDefault ? {} : { style: { objectFit: fit, objectPosition: settings.position } };

  return (
    <EditableSlot slot={slot}>
      <div className="mk-photo" {...hook}>
        <img
          // Re-keying forces a brand new request when we drop the CORS attempt.
          key={useCors ? 'cors' : 'plain'}
          src={src}
          alt=""
          {...(useCors ? { crossOrigin: 'anonymous' as const } : {})}
          // Untouched slots emit no inline style at all, so their DOM is
          // byte-for-byte what it was before MMX-007.
          {...inline}
          onError={() => (useCors ? setUseCors(false) : setFailed(true))}
        />
      </div>
    </EditableSlot>
  );
}

/* ============================================================
 *  IN-PREVIEW IMAGE EDITING  (MTC-MMX-007)
 * ============================================================
 *  Wraps a photo container so a file can be dropped straight
 *  onto the image you are looking at, rather than hunting for
 *  the matching field in the sidebar.
 *
 *  Everything it adds carries `data-export-skip`, which the PNG
 *  exporter already strips, so none of it reaches the rendered
 *  image. With no provider — the exported website — the wrapper
 *  renders its child and nothing else.
 * ============================================================ */

const MAX_SLOT_BYTES = 4 * 1024 * 1024;

function SlotControls({ slot }: { slot: string }) {
  const { settings, onImage, onSettings, device } = useContext(ImageSettingsContext);
  const [open, setOpen] = useState(false);
  const [tab, setTab] = useState<DeviceId>(device);
  const inputRef = useRef<HTMLInputElement>(null);

  if (!onImage) return null;

  const current = settings[slot] || {
    desktop: { ...DEFAULT_IMAGE_SETTINGS },
    mobile: { ...DEFAULT_IMAGE_SETTINGS },
  };
  const active = current[tab];

  const take = (file: File | undefined) => {
    if (!file || !file.type.startsWith('image/') || file.size > MAX_SLOT_BYTES) return;
    const reader = new FileReader();
    reader.onload = () => onImage(slot, String(reader.result || ''));
    reader.readAsDataURL(file);
  };

  const patch = (change: Partial<ImageSettings>) =>
    onSettings?.(slot, { ...current, [tab]: { ...active, ...change } });

  return (
    <div className="mk-slot-ui" data-export-skip>
      <div className="mk-slot-actions">
        <button type="button" title="Replace image" onClick={() => inputRef.current?.click()}>
          <FaImage />
        </button>
        <button type="button" title="Image settings" onClick={() => setOpen((v) => !v)}>
          <FaCog />
        </button>
        <button type="button" title="Remove image" onClick={() => onImage(slot, '')}>
          <FaTrash />
        </button>
      </div>

      {open && (
        <div className="mk-slot-popup">
          <div className="mk-slot-tabs">
            {(['desktop', 'mobile'] as DeviceId[]).map((d) => (
              <button
                key={d}
                type="button"
                className={tab === d ? 'is-active' : undefined}
                onClick={() => setTab(d)}
              >
                {d === 'desktop' ? 'Desktop' : 'Mobile'}
              </button>
            ))}
          </div>
          {([
            ['Size', IMAGE_SIZES, 'size'],
            ['Position', IMAGE_POSITIONS, 'position'],
            ['Repeat', IMAGE_REPEATS, 'repeat'],
          ] as const).map(([label, options, key]) => (
            <div key={key}>
              <span className="mk-slot-label">{label}</span>
              <div className="mk-slot-chips">
                {options.map((option) => (
                  <button
                    key={option}
                    type="button"
                    aria-pressed={active[key] === option}
                    onClick={() => patch({ [key]: option } as Partial<ImageSettings>)}
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        hidden
        onChange={(e) => {
          take(e.target.files?.[0]);
          e.target.value = '';
        }}
      />
    </div>
  );
}

/**
 * Makes one photo container editable in the builder. Renders its child
 * untouched everywhere else.
 */
export function EditableSlot({ slot, children }: { slot?: string; children: React.ReactNode }) {
  const { onImage } = useContext(ImageSettingsContext);
  const [over, setOver] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  if (!onImage || !slot) return <>{children}</>;

  const take = (file: File | undefined) => {
    if (!file || !file.type.startsWith('image/') || file.size > MAX_SLOT_BYTES) return;
    const reader = new FileReader();
    reader.onload = () => onImage(slot, String(reader.result || ''));
    reader.readAsDataURL(file);
  };

  return (
    <span
      className={`mk-slot${over ? ' is-over' : ''}`}
      data-slot-edit={slot}
      onDragOver={(e) => {
        e.preventDefault();
        e.stopPropagation();
        setOver(true);
      }}
      onDragLeave={() => setOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        e.stopPropagation();
        setOver(false);
        take(e.dataTransfer.files?.[0]);
      }}
      onDoubleClick={() => inputRef.current?.click()}
      title="Drop an image here, or double-click to choose one"
    >
      {children}
      {/* Several designs lay a gradient veil over the photo, which would eat
          the hover and the drop. This layer sits above any such overlay so the
          container is always reachable — it is transparent and excluded from
          the PNG, so it changes nothing about the mockup itself. */}
      <span className="mk-slot-layer" data-export-skip>
        <span className="mk-slot-hint">Drop image</span>
        <SlotControls slot={slot} />
      </span>
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        hidden
        onChange={(e) => {
          take(e.target.files?.[0]);
          e.target.value = '';
        }}
      />
    </span>
  );
}

/** Five static stars, exactly how both templates render a rating. */
export function Stars({ className = 'mk-stars' }: { className?: string }) {
  return (
    <span className={className}>
      {[0, 1, 2, 3, 4].map((i) => (
        <FaStar key={i} />
      ))}
    </span>
  );
}

export interface TrustPoint {
  icon: IconKey;
  title: string;
  description: string;
}

/**
 * The "why choose us" rows. Every one of these is derived from what the rep
 * typed, so the mockup speaks about the actual business rather than filler.
 */
export function buildTrustPoints(view: MockupView): TrustPoint[] {
  // buildView() returns '' for anything the business never told us, so every
  // sentence below is assembled from what actually exists. Interpolating a
  // blank straight into copy is what produced "every job in  — done properly"
  // and "Serving ." once the invented fallbacks were removed.
  const inArea = view.serviceArea ? ` in ${view.serviceArea}` : '';
  const servingArea = view.serviceArea ? ` Serving ${view.serviceArea}.` : '';

  const points: TrustPoint[] = [
    {
      icon: 'tools',
      title: view.hasYears ? `${view.years}+ Years On The Tools` : 'Craftsmanship First',
      description: `Real experience behind every job${inArea} — done properly the first time, not patched over.`,
    },
    {
      icon: 'home',
      title: view.addressShort ? `Local To ${view.addressShort}` : 'Local & Independent',
      description: `We are based right here and we answer the phone ourselves.${servingArea}`,
    },
  ];

  // A credential is a claim about the business — only make it if they made it.
  if (view.hasCredential) {
    points.splice(1, 0, {
      icon: 'shield',
      title: view.credential,
      description:
        'Fully covered before we set foot on site, so your property and your peace of mind are protected.',
    });
  }

  // Likewise a star rating: needs both the score and the count to say anything
  // truthful, so it is all-or-nothing.
  if (view.hasRating && view.hasReviewCount) {
    points.push({
      icon: 'shield',
      title: `${view.rating} Star Rated`,
      description: `${view.reviewCount}+ customers have left us a review — read them before you decide.`,
    });
  }

  return points;
}

/** Three short proof bullets used inside the service cards. */
export function buildFeatureBullets(view: MockupView): string[] {
  // Empty entries are dropped rather than rendered as a tick with no text.
  return [
    'Free, no-obligation quote',
    view.hasCredential ? view.credential : '',
    view.hasYears ? `${view.years}+ years experience` : 'Local, in-house crews',
  ].filter(Boolean);
}

/** Header nav links — the same set every template shows. */
export const NAV_LINKS: { label: string; href: string }[] = [
  { label: 'Home', href: 'home' },
  { label: 'Services', href: '#services' },
  { label: 'About', href: '#about' },
  { label: 'Reviews', href: '#reviews' },
  { label: 'Contact', href: '#contact' },
];

/**
 * The nav for one particular site.
 *
 * On the WEBSITE, "Reviews" only earns a place when there is a review section
 * to jump to — a business with no rating on file would otherwise ship a link
 * to an anchor that does not exist.
 *
 * The MOCKUP keeps all five regardless. There the nav is inert decoration in
 * a picture, nothing can be clicked, and dropping an item would change the
 * design Nate signed off on. Filtering is a website concern only.
 */
export function navLinks(
  view: MockupView,
  site: boolean,
  /**
   * Anchors this template does NOT render for this data. A design whose
   * "about" section disappears when there is no about copy passes '#about',
   * and the nav item goes with it rather than pointing at nothing.
   */
  missing: string[] = [],
): { label: string; href: string }[] {
  if (!site) return NAV_LINKS;
  const hasReviews = view.hasRating || view.hasReviewCount;
  return NAV_LINKS.filter((link) => {
    if (missing.includes(link.href)) return false;
    return link.href === '#reviews' ? hasReviews : true;
  });
}

/* ============================================================
 *  SITE CHROME  (MTC-MMX-006)
 * ============================================================
 *  These templates are rendered two ways.
 *
 *    MOCKUP   a picture that gets rasterised to PNG. Every
 *             clickable-looking thing is an inert <span>, and
 *             MMX-006 must not change that by a single byte.
 *
 *    WEBSITE  a real multi-page site exported into /out, where
 *             the same elements have to be real links.
 *
 *  So the templates ask for a link and get whichever the
 *  current context calls for. With no provider — which is the
 *  mockup — `site` is false and <A> renders the same <span>
 *  the template used before, with the same className and the
 *  same children. `scripts/snapshot-mockup.mjs` holds that
 *  guarantee to a byte-for-byte DOM comparison.
 * ============================================================ */

/** The pages the exporter generates. */
export type PageId = 'home' | 'services' | 'privacy' | 'terms';

/** How deep each page sits, for building relative links. */
const PAGE_DEPTH: Record<PageId, number> = { home: 0, services: 1, privacy: 1, terms: 1 };

/** Directory of each page relative to the site root. */
const PAGE_DIR: Record<PageId, string> = {
  home: '',
  services: 'services/',
  privacy: 'privacy/',
  terms: 'terms/',
};

export interface SiteContextValue {
  /** True only in the exported website. */
  site: boolean;
  /** Which generated page is rendering. */
  page: PageId;
}

const SiteContext = createContext<SiteContextValue>({ site: false, page: 'home' });

export const SiteProvider = SiteContext.Provider;

export function useSite(): SiteContextValue {
  return useContext(SiteContext);
}

/**
 * A link destination, written the same way in every template.
 *
 *   'home' | 'services' | 'privacy' | 'terms'   a generated page
 *   '#services'                                 a section of the home page
 *   'tel:…' | 'mailto:…' | 'https://…'          an external destination
 *
 * Relative hrefs are used throughout so the site works at a domain root, in
 * a subfolder, or on GitHub Pages without any configuration — the same
 * reason vite.config sets `base: './'`.
 */
export function resolveHref(target: string, page: PageId): string {
  if (/^(tel:|mailto:|https?:|sms:)/i.test(target)) return target;

  const up = '../'.repeat(PAGE_DEPTH[page]);

  // A section of the home page.
  if (target.startsWith('#')) {
    return page === 'home' ? target : `${up}${target}`;
  }

  const id = target as PageId;
  if (id in PAGE_DIR) {
    const dir = PAGE_DIR[id];
    // './' rather than '' so the href is never empty.
    return `${up}${dir}` || './';
  }

  return target;
}

/**
 * An anchor target that only exists on the website.
 *
 * Two of the four designs never had a `#reviews` section to land on. Adding
 * the id unconditionally would change the mockup's DOM, which MMX-006 is not
 * allowed to do — so it is attached only when a real site is rendering.
 * Spread it onto the element: `{...anchorId('reviews', site)}`.
 */
export function anchorId(id: string, site: boolean): { id?: string } {
  return site ? { id } : {};
}

/** Builds a Google Maps search link for an address. Empty in, empty out. */
export function mapHref(address: string): string {
  const query = (address || '').trim();
  return query
    ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`
    : '';
}

export interface AProps {
  /** Where it goes, in the resolveHref vocabulary. Empty means not a link. */
  href: string;
  className?: string;
  children?: React.ReactNode;
  /** The element the MOCKUP renders. Must match what the template used before. */
  as?: 'span' | 'div' | 'li' | 'article';
  /** Opens in a new tab, for destinations that leave the site. */
  external?: boolean;
  'aria-label'?: string;
  title?: string;
}

/**
 * The one place a template asks for a link.
 *
 * In the mockup this is the inert element it always was. On the website it is
 * a real anchor. An empty href renders the inert element too, so a template
 * can hand over `v.phoneHref` without first checking it — though the caller
 * should still hide the element entirely when the underlying fact is missing,
 * since a business with no phone should show no call button at all.
 */
export function A({
  href,
  className,
  children,
  as: Tag = 'span',
  external,
  ...rest
}: AProps) {
  const { site, page } = useSite();

  // No provider (the mockup), or nothing to point at: the inert element the
  // template always rendered.
  if (!site || !href) {
    return (
      <Tag className={className} {...rest}>
        {children}
      </Tag>
    );
  }

  const resolved = resolveHref(href, page);
  const leavesSite = external ?? /^(https?:)/i.test(resolved);

  return (
    <a
      className={className}
      href={resolved}
      {...(leavesSite ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
      {...rest}
    >
      {children}
    </a>
  );
}

/**
 * Nav items, with the section each one points at.
 *
 * `NAV_LINKS` above is kept as-is so nothing that still reads it breaks. This
 * carries the real targets, plus which view flag has to be true for the
 * destination to exist — a nav item whose section is hidden would otherwise
 * scroll nowhere.
 */
export interface NavItem {
  label: string;
  target: string;
  /** Reads the view and says whether this item's destination exists. */
  exists: (view: MockupView) => boolean;
}

export const NAV_ITEMS: NavItem[] = [
  { label: 'Home', target: 'home', exists: () => true },
  { label: 'Services', target: '#services', exists: () => true },
  { label: 'About', target: '#about', exists: (v) => v.hasAbout },
  { label: 'Reviews', target: '#reviews', exists: (v) => v.hasRating || v.hasReviewCount },
  { label: 'Contact', target: '#contact', exists: () => true },
];

/**
 * The nav for the current context.
 *
 * The mockup always gets all five, so its DOM is unchanged. The website drops
 * any whose target section is not rendered, because a nav item that scrolls
 * nowhere is exactly the dead link this ticket exists to remove.
 */
export function useNavItems(view: MockupView): NavItem[] {
  const { site } = useSite();
  return site ? NAV_ITEMS.filter((item) => item.exists(view)) : NAV_ITEMS;
}
