/**
 * ============================================================
 *  MOCKUP DATA MODEL
 * ============================================================
 *  This is the single shape that drives every template render
 *  AND the shape of the exported JSON. It mirrors the fields
 *  that live in each template's `src/content.tsx`.
 * ============================================================
 */

export type TemplateId = 'v2' | 'v3' | 'clean' | 'studio' | 'signature';
export type ThemeMode = 'light' | 'dark';
export type DeviceId = 'desktop' | 'mobile';

/** Sentinel meaning "deliberately no photo" — an empty string means "auto-pick". */
export const NO_IMAGE = 'none';

export interface ServiceEntry {
  /** Service name, e.g. "Roofing" */
  title: string;
  /** One-line sales description shown on the card */
  description: string;
  /**
   * Optional card photo.
   *   ''      → auto-match a photo from the service name
   *   'none'  → no photo, render the branded gradient panel instead
   *   <url>   → use this exact image
   */
  image?: string;
}

/**
 * ============================================================
 *  IMAGE SLOTS  (MTC-MMX-007)
 * ============================================================
 *  Every photo on a template sits in a named slot:
 *
 *      hero          the hero background
 *      service-0..n  one per service card, by index
 *      gallery-0..n  one per "our work" photo, by index
 *
 *  The slot id is the join between three things: the drag/drop
 *  UI in the builder, the crop settings below, and the
 *  automatic population of legacy images (MTC-MMX-008). An
 *  image dropped by hand and one mapped from a data dump are
 *  the same thing once they land in a slot — there is
 *  deliberately no flag distinguishing them.
 * ============================================================
 */
export type ImageSlotId = string;

/** How a photo is cropped inside its slot. CSS-only, per Nate's brief. */
export interface ImageSettings {
  /** background-size */
  size: 'cover' | 'contain' | 'auto';
  /** background-position, e.g. 'center', 'top left' */
  position: string;
  /** background-repeat */
  repeat: 'no-repeat' | 'repeat';
}

/**
 * Desktop and mobile are configured separately, so a photo can be framed
 * one way on a wide screen and another on a phone. Changing one never
 * touches the other.
 */
export interface ImageSlotSettings {
  desktop: ImageSettings;
  mobile: ImageSettings;
}

/** What an untouched slot uses. Matches the CSS the templates already had. */
export const DEFAULT_IMAGE_SETTINGS: ImageSettings = {
  size: 'cover',
  position: 'center',
  repeat: 'no-repeat',
};

export const DEFAULT_SLOT_SETTINGS: ImageSlotSettings = {
  desktop: { ...DEFAULT_IMAGE_SETTINGS },
  mobile: { ...DEFAULT_IMAGE_SETTINGS },
};

/** The positions offered in the settings popup. */
export const IMAGE_POSITIONS = [
  'center',
  'top',
  'bottom',
  'left',
  'right',
  'top left',
  'top right',
  'bottom left',
  'bottom right',
] as const;

export const IMAGE_SIZES: ImageSettings['size'][] = ['cover', 'contain', 'auto'];
export const IMAGE_REPEATS: ImageSettings['repeat'][] = ['no-repeat', 'repeat'];

/**
 * Reads a slot-settings map back off imported JSON, keeping only values the
 * renderer can actually use. An unknown size, a nonsense position or a
 * hand-edited half-object falls back to the default rather than reaching CSS.
 */
export function parseImageSettings(raw: unknown): Record<ImageSlotId, ImageSlotSettings> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  const out: Record<ImageSlotId, ImageSlotSettings> = {};

  const one = (value: unknown): ImageSettings => {
    const v = (value || {}) as Partial<ImageSettings>;
    return {
      size: IMAGE_SIZES.includes(v.size as ImageSettings['size'])
        ? (v.size as ImageSettings['size'])
        : DEFAULT_IMAGE_SETTINGS.size,
      position:
        typeof v.position === 'string' &&
        (IMAGE_POSITIONS as readonly string[]).includes(v.position)
          ? v.position
          : DEFAULT_IMAGE_SETTINGS.position,
      repeat: IMAGE_REPEATS.includes(v.repeat as ImageSettings['repeat'])
        ? (v.repeat as ImageSettings['repeat'])
        : DEFAULT_IMAGE_SETTINGS.repeat,
    };
  };

  for (const [slot, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!slot || !value || typeof value !== 'object') continue;
    const entry = value as Partial<ImageSlotSettings>;
    out[slot] = { desktop: one(entry.desktop), mobile: one(entry.mobile) };
  }
  return out;
}

/** True when a slot is still at its defaults, so it can be left out of the JSON. */
export function isDefaultSlotSettings(value: ImageSlotSettings | undefined): boolean {
  if (!value) return true;
  const same = (a: ImageSettings) =>
    a.size === DEFAULT_IMAGE_SETTINGS.size &&
    a.position === DEFAULT_IMAGE_SETTINGS.position &&
    a.repeat === DEFAULT_IMAGE_SETTINGS.repeat;
  return same(value.desktop) && same(value.mobile);
}

/**
 * Outbound destinations for the business. Every one is optional: an empty
 * string means "this business has no such link", and the exported website
 * hides the element rather than inventing a destination.
 *
 * The mockup does not render these — it is a picture. They exist so the
 * exported WEBSITE can wire its social and review buttons to real places.
 */
export interface SiteLinks {
  /** An existing website for the business, if it has one elsewhere. */
  website: string;
  facebook: string;
  instagram: string;
  yelp: string;
  /** Google Business Profile / search listing. */
  google: string;
  nextdoor: string;
  /** Where a customer goes to leave a review. */
  leaveReview: string;
}

export interface MockupData {
  // ── Business ────────────────────────────────
  businessName: string;
  /**
   * What this business DOES, as a noun a headline can complete: "Roofing",
   * "Plumbing & Heating", "Custom Carpentry". It is the subject of the hero
   * headline, the About heading and the closing call to action.
   *
   * MTC-MMX-009. Deliberately NOT a service. Services are countable
   * deliverables ("Roof Replacement"); this is the trade itself. It never
   * appears in the services grid, the nav or the footer list, and nothing
   * derives an icon, slug or photo from it. Before this field existed those
   * headlines read `services[0].title`, so renaming Service 1 silently
   * rewrote the whole site's identity — the bug this replaces.
   *
   * Blank is normal and safe. While it is blank every headline falls back to
   * the first service exactly as it did before, so existing, re-imported and
   * migrated sites render unchanged.
   */
  trade: string;
  /** Slogan / tagline shown under the logo and in the hero */
  slogan: string;
  phone: string;
  email: string;
  address: string;
  /** e.g. "Boise, Meridian & All Across the Treasure Valley" */
  serviceArea: string;

  // ── Brand ───────────────────────────────────
  /** Primary brand colour (HEX) */
  primaryColor: string;
  /** Secondary / accent brand colour (HEX) */
  secondaryColor: string;
  /** Optional hero background photo URL */
  heroImage: string;
  /**
   * The business's own logo (MTC-MMX-013). Templates built around a logo
   * show it large; the rest ignore it. Empty is normal and safe — every
   * template falls back to the monogram built from the business name
   * rather than inventing a mark the business does not have.
   */
  logoImage: string;
  /**
   * "Our work" photos. Optional — the section is hidden entirely when this
   * is empty rather than filled with stock images of somebody else's jobs.
   */
  gallery: string[];

  // ── Content ─────────────────────────────────
  /** Exactly three services drive the nav, cards and footer */
  services: ServiceEntry[];
  /** About-us paragraph */
  aboutText: string;

  // ── Trust / extras (optional, still part of content.tsx) ──
  hours: string;
  reviewRating: string;
  reviewCount: string;
  yearsInBusiness: string;
  /** e.g. "Licensed & Insured" */
  credential: string;

  // ── Outbound links (website export only) ────
  /** Social, review and website destinations. Absent ones stay empty. */
  links: SiteLinks;

  /**
   * Crop settings per image slot (MTC-MMX-007), keyed by slot id — 'hero',
   * 'service-0', 'gallery-3'. Only slots the user actually adjusted appear
   * here; everything else falls back to DEFAULT_SLOT_SETTINGS, which keeps
   * the JSON small and old exports readable.
   */
  imageSettings: Record<ImageSlotId, ImageSlotSettings>;
}

/** The slot id for a service card photo. */
export const serviceSlot = (index: number): ImageSlotId => `service-${index}`;
/** The slot id for a gallery photo. */
export const gallerySlot = (index: number): ImageSlotId => `gallery-${index}`;
/** The hero's slot id. */
export const HERO_SLOT: ImageSlotId = 'hero';
/** The logo's slot id, so it gets the same drag/drop and crop controls. */
export const LOGO_SLOT: ImageSlotId = 'logo';

/** Every link empty — the honest default for a business with none on file. */
export const EMPTY_LINKS: SiteLinks = {
  website: '',
  facebook: '',
  instagram: '',
  yelp: '',
  google: '',
  nextdoor: '',
  leaveReview: '',
};

/** Everything needed to reproduce a mockup, including presentation options. */
export interface MockupProject {
  /** Schema version so old exports stay readable */
  version: 1;
  template: TemplateId;
  mode: ThemeMode;
  data: MockupData;
}

export interface TemplateProps {
  data: MockupData;
  mode: ThemeMode;
  device: DeviceId;
  /**
   * Which generated page to render (website export only). Absent means the
   * home page, which is the only thing the mockup ever renders — so the
   * mockup's output is unchanged by this existing.
   */
  page?: 'home' | 'services' | 'privacy' | 'terms';
}
