import React from "react";
import {
  FaArrowRight,
  FaAward,
  FaBars,
  FaCalculator,
  FaCalendarCheck,
  FaCheckCircle,
  FaChevronDown,
  FaClock,
  FaComments,
  FaDollarSign,
  FaEnvelope,
  FaFacebookF,
  FaFolderOpen,
  FaGoogle,
  FaHardHat,
  FaImages,
  FaList,
  FaMapMarkerAlt,
  FaPhoneAlt,
  FaQuoteLeft,
  FaShieldAlt,
  FaStar,
} from 'react-icons/fa';
import { SecondaryPage } from '../pages';
import { gallerySlot, HERO_SLOT, serviceSlot } from '../../types';
import type { TemplateProps } from '../../types';
import { buildTheme, tokensToStyle } from '../../lib/color';
import { buildView } from '../../lib/viewModel';
import { A, anchorId, useSite, buildFeatureBullets, ImageSettingsProvider, navLinks, Photo, Stars } from '../shared';
import ServiceIcon from '../../components/ServiceIcon';
import '../base.css';
import './v3.css';

/** True only when the business actually supplied the value. */
const has = (value: string | undefined): boolean => Boolean((value || '').trim());

/**
 * Free Website template v3 — light, photo-led layout with a floating pill
 * header over a full-bleed hero, a glass review card, image-topped service
 * cards and a dark CTA band. Structure mirrors template--free-web-v3.
 *
 * These renders ship as real, published client websites, so every business
 * fact below is rendered only when the business actually gave us one. An
 * absent fact removes its whole element — the stat tile, the chip, the contact
 * line — rather than leaving an empty box or a dangling label, and it is never
 * swapped for an invented stand-in. The rails that hold those elements are
 * told how many survived so they still lay out correctly with fewer.
 */
export default function TemplateV3({ data, mode, device, page = 'home' }: TemplateProps) {
  const v = buildView(data);
  // An absent credential comes back as an empty bullet — drop it rather than
  // render a tick with nothing beside it.
  const bullets = buildFeatureBullets(v).filter(has);
  const city = v.city;
  const hasCity = Boolean(city);

  const hasPhone = has(v.phone);
  const hasEmail = has(v.email);
  const hasAddress = has(v.addressShort) || has(v.address);
  const hasHours = has(v.hours);
  const hasCredential = has(v.credential);
  const hasArea = has(v.serviceArea);
  const hasRating = v.hasRating && has(v.rating);
  const hasReviewCount = has(v.reviewCount);
  /** Any genuine review proof at all — gates every rating flourish on the page. */
  const hasReviews = hasRating || hasReviewCount;

  // True only in the exported website, never in the mockup.
  const { site } = useSite();

  const showTopbar = hasPhone || hasEmail || hasCredential;
  const showStats = hasReviews || hasCredential;
  const showImageBadge = hasCredential || hasRating;
  // Two of these chips are claims about how we work, not facts about the
  // business record; the other two only appear when the data backs them.
  const trustChipCount = 2 + (hasCredential ? 1 : 0) + (hasRating ? 1 : 0);
  const ctaTrustCount = 2 + (hasCredential ? 1 : 0);

  // Inline custom properties — see the note in TemplateV2.
  const theme = tokensToStyle(buildTheme(data.primaryColor, data.secondaryColor, mode, 'v3'));

  return (
    // Publishes the per-slot crop settings for <Photo>. Renders no DOM of
    // its own, so the markup below is unchanged.
    <ImageSettingsProvider data={data} device={device}>
    <div className="mk mk-v3" style={theme} data-mode={mode} data-device={device}>
      {/* ── HEADER ─────────────────────────────── */}
      <header className={`v3-header${showTopbar ? '' : ' is-bare'}`}>
        {showTopbar && (
          <div className="v3-topbar">
            <div className="v3-container v3-topbar-inner">
              <div className="v3-topbar-left">
                {hasPhone && (
                  <span className="v3-topbar-link">
                    <FaPhoneAlt /> {v.phone}
                  </span>
                )}
                {hasPhone && hasEmail && <span className="v3-topbar-divider">|</span>}
                {hasEmail && (
                  <span className="v3-topbar-link">
                    <FaEnvelope /> {v.email}
                  </span>
                )}
              </div>
              {hasCredential && (
                <span className="v3-badge-pill">
                  <FaStar /> {v.credential}
                </span>
              )}
            </div>
          </div>
        )}

        <div className="v3-container">
          <div className="v3-nav-wrap">
            <div className="v3-logo">
              <span className="mk-monogram">{v.initials}</span>
              <span className="v3-logo-text">
                {v.lead} {v.accent && <em>{v.accent}</em>}
              </span>
            </div>

            <ul className="v3-nav-list">
              {navLinks(v, site).map((link, i) => (
                <li key={link.label}>
                  <A href={link.href} className={`v3-nav-link${i === 0 ? ' is-active' : ''}`}>
                    {link.label}
                    {link.label === 'Services' && <FaChevronDown />}
                  </A>
                </li>
              ))}
            </ul>

            <A href="#contact" className="v3-nav-cta">
              Get a Quote
              <span className="v3-nav-cta-icon">
                <FaArrowRight />
              </span>
            </A>

            <span className="v3-burger">
              <FaBars />
            </span>
          </div>
        </div>
      </header>

      {/* Generated pages reuse the header and footer; only the body swaps. */}
      {page !== 'home' ? (
        <SecondaryPage page={page} view={v} p="v3" name={v.name} />
      ) : (
      <>

      {/* ── HERO ───────────────────────────────── */}
      <section className="v3-hero">
        <Photo src={v.heroImage} slot={HERO_SLOT} />
        <div className="v3-hero-overlay" />

        <div className={`v3-hero-inner${hasReviews ? '' : ' is-solo'}`}>
          <div>
            <span className="v3-trust-badge">
              <FaCheckCircle />{' '}
              {hasCredential ? `${v.credential} • Free Estimates` : 'Free Estimates'}
            </span>

            <h1 className="v3-hero-title">
              Expert {v.trade} {hasCity && <em>Across {city}</em>}
            </h1>

            {has(v.aboutShort) && <p className="v3-hero-desc">{v.aboutShort}</p>}

            {hasReviews && (
              <div className="v3-ratings">
                <div className="v3-rating-box">
                  <span className="v3-platform-icon" style={{ color: '#4285F4' }}>
                    <FaGoogle />
                  </span>
                  <span className="v3-rating-details">
                    {hasRating && (
                      <span className="v3-rating-top">
                        <Stars />
                        <span className="v3-rating-score">{v.rating}</span>
                      </span>
                    )}
                    <span className="v3-platform-name">
                      {hasReviewCount ? `${v.reviewCount} Google Reviews` : 'Google Reviews'}
                    </span>
                  </span>
                </div>

                {/* The original design showed a second rating box for Facebook.
                    There is exactly one rating figure in the data and nothing
                    that says anything about Facebook, so a second box could
                    only ever be a made-up score for a platform we have no
                    reading from. One honest box beats two, one of them fiction. */}
              </div>
            )}
          </div>

          {hasReviews && (
            <div className="v3-review-card" {...anchorId('reviews', site)}>
              <FaQuoteLeft className="v3-quote-icon" />
              <p className="v3-review-text">
                &ldquo;Turned up when they said they would, did a proper job and left the place
                spotless.{hasCity ? ` Would not use anyone else in ${city}.` : ''}&rdquo;
              </p>
              <div className="v3-reviewer">
                <span className="v3-reviewer-avatar">TM</span>
                <span>
                  <span className="v3-reviewer-name">Tom Metcalf</span>
                  <span className="v3-reviewer-rating">
                    <Stars />
                    <span className="v3-reviewer-score">5.0</span>
                  </span>
                </span>
              </div>
            </div>
          )}
        </div>

        <div className="v3-bottom-bar">
          <div className="v3-bottom-wrap">
            <nav className="v3-bottom-nav">
              <A href="services" className="v3-bottom-link">
                <FaList /> Services
              </A>
              {(!site || v.hasGallery) && (
                <A href="#gallery" className="v3-bottom-link">
                  <FaFolderOpen /> Past Projects
                </A>
              )}
              <A href="#contact" className="v3-bottom-link">
                <FaComments /> Request Quote
              </A>
              {(!site || hasReviews) && (
                <A href="#reviews" className="v3-bottom-link">
                  <FaStar /> Reviews
                </A>
              )}
            </nav>
            <A href="#contact" className="v3-bottom-cta">
              Get A Free Quote
            </A>
          </div>
        </div>
      </section>

      {/* ── ABOUT ──────────────────────────────── */}
      <section className="v3-about" id="about">
        <div className="v3-container v3-about-grid">
          <div>
            <span className="v3-tag">
              <FaAward /> About {v.name}
            </span>

            <h2 className="v3-about-title">
              {has(v.sloganLead) && (
                <>
                  {v.sloganLead},
                  <br />
                </>
              )}
              Done The Right Way
            </h2>

            {has(v.aboutText) && <p className="v3-about-desc">{v.aboutText}</p>}

            {showStats && (
              <div className="v3-stats">
                {hasReviews && (
                  <div className="v3-stat">
                    <FaStar className="is-star" />
                    <span className="v3-stat-info">
                      <strong>{hasRating ? `${v.rating} ★` : `${v.reviewCount}+`}</strong>
                      <span>
                        {hasReviewCount ? `${v.reviewCount}+ Google Reviews` : 'Google Reviews'}
                      </span>
                    </span>
                  </div>
                )}
                {hasCredential && (
                  <div className="v3-stat">
                    <FaCheckCircle />
                    <span className="v3-stat-info">
                      <strong>{v.credential}</strong>
                      <span>Covered on every job</span>
                    </span>
                  </div>
                )}
              </div>
            )}

            <div className="v3-highlights">
              <span className="v3-highlight">
                <FaHardHat /> {v.services.map((s) => s.title).join(' • ')}
              </span>
              {hasArea && (
                <span className="v3-highlight">
                  <FaMapMarkerAlt /> Serving {v.serviceArea}
                </span>
              )}
              {hasHours && (
                <span className="v3-highlight">
                  <FaClock /> {v.hours}
                </span>
              )}
              <span className="v3-highlight">
                <FaDollarSign /> Competitive Prices • No Hidden Fees
              </span>
            </div>

            <A href="#contact" className="v3-about-cta">
              Get Your Free Quote <FaArrowRight />
            </A>
          </div>

          <div className="v3-about-image">
            <div className="v3-image-wrapper">
              <Photo src={v.heroImage} slot={HERO_SLOT} />
              <div className="v3-image-overlay">
                <FaCheckCircle />
                {v.hasYears
                  ? `Over ${v.years} years${hasCity ? ` in ${city}` : ''}`
                  : hasCity
                    ? `Trusted across ${city}`
                    : 'Trusted by local homeowners'}
              </div>
            </div>
            {showImageBadge && (
              <div className="v3-image-badge">
                {hasCredential && <strong>{v.credential}</strong>}
                {hasRating && <span>{v.rating} ★ Rated</span>}
              </div>
            )}
          </div>
        </div>
      </section>

      {/* ── SERVICES ───────────────────────────── */}
      <section className="v3-services" id="services">
        <div className="v3-container">
          <div className="v3-services-head">
            <span className="v3-tag">
              <FaHardHat /> Our Expertise
            </span>
            <h2 className="v3-services-title">Complete Solutions For Every Project</h2>
            <p className="v3-services-sub">
              From the smallest repair to a full replacement, our team has the right solution for the
              job — priced fairly and delivered on time
              {hasArea ? ` across ${v.serviceArea}` : ''}.
            </p>
          </div>

          <div className="v3-trust-strip" data-count={trustChipCount}>
            {hasCredential && (
              <div className="v3-chip">
                <span className="v3-chip-icon">
                  <FaShieldAlt />
                </span>
                <span className="v3-chip-text">
                  <strong>{v.credential}</strong>
                  <small>Covered on every job</small>
                </span>
              </div>
            )}
            <div className="v3-chip">
              <span className="v3-chip-icon">
                <FaHardHat />
              </span>
              <span className="v3-chip-text">
                <strong>Trained Crews</strong>
                <small>No subcontractors</small>
              </span>
            </div>
            <div className="v3-chip">
              <span className="v3-chip-icon">
                <FaClock />
              </span>
              <span className="v3-chip-text">
                <strong>Rapid Response</strong>
                <small>Same-week bookings</small>
              </span>
            </div>
            {hasRating && (
              <div className="v3-chip">
                <span className="v3-chip-icon">
                  <FaStar />
                </span>
                <span className="v3-chip-text">
                  <strong>{v.rating}★ Rated</strong>
                  <small>{hasCity ? `Trusted in ${city}` : 'Trusted locally'}</small>
                </span>
              </div>
            )}
          </div>

          <div className="v3-services-grid">
            {v.services.map((service, i) => (
              <article className="v3-card" key={service.slug}>
                <div className="v3-card-media">
                  <Photo src={service.image} slot={serviceSlot(i)} />
                  {!service.image && (
                    <span className="v3-card-glyph">
                      <ServiceIcon name={service.icon} />
                    </span>
                  )}
                  <div className="v3-card-media-veil" />
                  {hasCredential && <span className="v3-card-badge">{v.credential}</span>}
                  <span className="v3-card-icon">
                    <ServiceIcon name={service.icon} />
                  </span>
                </div>

                <div className="v3-card-body">
                  <h3 className="v3-card-title">{service.title}</h3>
                  <p className="v3-card-desc">{service.description}</p>
                  {bullets.length > 0 && (
                    <ul className="v3-card-features">
                      {bullets.map((bullet) => (
                        <li key={bullet}>
                          <FaCheckCircle /> {bullet}
                        </li>
                      ))}
                    </ul>
                  )}
                  <div className="v3-card-actions">
                    <A href="services" className="v3-card-btn">
                      Learn More <FaArrowRight />
                    </A>
                    {(!site || v.hasPhone) && (
                      <A
                        href={v.phoneHref}
                        className="v3-card-call"
                        // An icon-only link needs a name for screen readers,
                        // but adding one in the mockup would change its DOM.
                        {...(site ? { 'aria-label': `Call ${v.phone}` } : {})}
                      >
                        <FaPhoneAlt />
                      </A>
                    )}
                  </div>
                </div>
              </article>
            ))}
          </div>

          <div className="v3-cta-bar">
            <div className="v3-cta-bar-text">
              <h3>Not sure which service you need?</h3>
              <p>
                We will visit your property, take a proper look and recommend the most cost-effective
                fix — free of charge, with no pressure to book.
              </p>
            </div>
            <div className="v3-cta-bar-actions">
              {hasPhone && (
                <A href={v.phoneHref} className="v3-cta-bar-primary">
                  <FaPhoneAlt /> Call {v.phone}
                </A>
              )}
              <A href="#contact" className="v3-cta-bar-secondary">
                Request Free Quote <FaArrowRight />
              </A>
            </div>
          </div>
        </div>
      </section>

      {/* ── OUR WORK ───────────────────────────── */}
      {v.hasGallery && (
        <section className="v3-work" id="gallery">
          <div className="v3-container">
            <div className="v3-services-head">
              <span className="v3-tag">
                <FaImages /> Our Work
              </span>
              <h2 className="v3-services-title">Recent Projects</h2>
              <p className="v3-services-sub">
                Every job finished to the same standard, whatever the size.
              </p>
            </div>
            <div className="v3-work-grid">
              {v.gallery.slice(0, 6).map((url, i) => (
                <figure className="v3-work-tile" key={`${url}-${i}`}>
                  <Photo src={url} slot={gallerySlot(i)} />
                </figure>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* ── CTA BAND ───────────────────────────── */}
      <section className="v3-cta" id="contact">
        <Photo />
        <div className="v3-cta-overlay" />

        <div className="v3-cta-inner">
          <div className="v3-cta-content">
            <span className="v3-cta-badge">Get Your Project Moving</span>
            <h2 className="v3-cta-title">
              The Trusted Name In
              <em>{hasCity ? `${city} ` : ''}{v.trade}</em>
            </h2>
            <p className="v3-cta-sub">
              Do not risk your property on an unreliable crew. Get a free, no-obligation quote from a
              {hasCredential ? ` ${v.credential.toLowerCase()}` : ''} local team.
            </p>
            <div className="v3-cta-actions">
              {hasPhone && (
                <A href={v.phoneHref} className="v3-cta-btn-primary">
                  <FaPhoneAlt /> Call {v.phone}
                </A>
              )}
              <A href="#contact" className="v3-cta-btn-secondary">
                <FaCalendarCheck /> Free Site Survey
              </A>
            </div>
          </div>

          <div className="v3-cta-trust" data-count={ctaTrustCount}>
            <div className="v3-cta-trust-item">
              <span className="v3-cta-trust-icon">
                <FaAward />
              </span>
              <h3>Trained Crews</h3>
              <p>Every person on site is trained, experienced and directly employed by us.</p>
            </div>
            {hasCredential && (
              <div className="v3-cta-trust-item">
                <span className="v3-cta-trust-icon">
                  <FaShieldAlt />
                </span>
                <h3>{v.credential}</h3>
                <p>Full cover on every job, big or small, before any work starts.</p>
              </div>
            )}
            <div className="v3-cta-trust-item">
              <span className="v3-cta-trust-icon">
                <FaCalculator />
              </span>
              <h3>Honest Pricing</h3>
              <p>Clear, itemised quotes with no surprises and no hidden extras.</p>
            </div>
          </div>
        </div>
      </section>

      {/* ── FOOTER ─────────────────────────────── */}
      </>
      )}

      <footer className="v3-footer">
        <div className="v3-container">
          <div className="v3-footer-grid">
            <div>
              <div className="v3-footer-logo">
                {v.lead} {v.accent && <em>{v.accent}</em>}
              </div>
              {has(v.aboutShort) && <p className="v3-footer-desc">{v.aboutShort}</p>}
            </div>

            <div>
              <h3 className="v3-footer-title">Quick Links</h3>
              <ul className="v3-footer-links">
                {navLinks(v, site).map((link) => (
                  <li key={link.label}>
                    <A href={link.href}>{link.label}</A>
                  </li>
                ))}
              </ul>
            </div>

            <div>
              <h3 className="v3-footer-title">Our Services</h3>
              <ul className="v3-footer-links">
                {v.services.map((service) => (
                  <li key={service.slug}>
                    <span>{service.title}</span>
                  </li>
                ))}
              </ul>
            </div>

            <div>
              <h3 className="v3-footer-title">Connect With Us</h3>
              <div className="v3-footer-social">
                <span>
                  <FaFacebookF /> Facebook
                </span>
                <span>
                  <FaGoogle /> Google Reviews
                </span>
                {hasAddress && (
                  <span>
                    <FaMapMarkerAlt /> {v.addressShort || v.address}
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="v3-footer-bottom">
            <p>
              © {v.year} {v.name}. All rights reserved.
              {/* Legal pages exist only on the exported website, so the link to
                  them does too — the mockup's footer is unchanged. */}
              {site && (
                <>
                  {' '}
                  <A href="privacy">Privacy Policy</A> · <A href="terms">Terms of Service</A>
                </>
              )}
            </p>
            {(hasPhone || hasEmail) && (
              <div className="v3-footer-contact">
                {hasPhone && (
                  <span>
                    <FaPhoneAlt /> {v.phone}
                  </span>
                )}
                {hasEmail && (
                  <span>
                    <FaEnvelope /> {v.email}
                  </span>
                )}
              </div>
            )}
          </div>
        </div>
      </footer>
    </div>
    </ImageSettingsProvider>
  );
}
