import React from "react";
import TemplateV3 from './templates/v3/TemplateV3';
import { SiteProvider } from './templates/shared';
import type { PageId } from './templates/shared';
import CONTENT, { MODE } from './content';
import './site.css';
import './templates/pages.css';

export default function Site({ page }: { page: PageId }) {
  return (
    <SiteProvider value={{ site: true, page }}>
      <TemplateV3 data={CONTENT} mode={MODE} device="desktop" page={page} />
    </SiteProvider>
  );
}
