import React from "react";
/**
 * ============================================================
 *  SECONDARY PAGES  (MTC-MMX-006)
 * ============================================================
 *  The exported website has more than a home page. These are
 *  the bodies of the extra ones; each template supplies its own
 *  header and footer around them, so a generated page looks
 *  native to whichever design was chosen rather than bolted on.
 *
 *  The mockup never renders any of this — it only ever draws
 *  the home page.
 *
 *  ── ON THE LEGAL PAGES ──────────────────────────────────────
 *  Privacy and Terms are the only pages here whose words are
 *  not the business's own, so they are written to the same rule
 *  as everything else in this project: state what is true of
 *  this actual website, and nothing more.
 *
 *  What is true: it is a static brochure site. No accounts, no
 *  logins, no payments, no shopping basket, no analytics, and
 *  no cookies set by the site itself. What IS worth disclosing
 *  is that the page pulls webfonts from Google, which means a
 *  visitor's IP address reaches Google — that is a real data
 *  transfer and saying nothing about it would be the dishonest
 *  option.
 *
 *  What is deliberately NOT here: any claim of GDPR, UK GDPR,
 *  CCPA or any other specific compliance; any named data
 *  protection officer; any retention schedule; and any
 *  governing-law or jurisdiction clause. A jurisdiction cannot
 *  be inferred from a mailing address without making a legal
 *  judgement, and inventing one is exactly the failure mode
 *  this codebase already refuses elsewhere.
 *
 *  These pages are a starting point that the business must have
 *  reviewed. build-site.mjs prints that warning on every export.
 * ============================================================
 */

import type { MockupView } from '../lib/viewModel';
import { A, mapHref } from './shared';

export interface PageBodyProps {
  view: MockupView;
  /** Template class prefix: 'v2' | 'v3' | 'cl' | 'st'. */
  p: string;
  /** The business name, for the legal copy. */
  name: string;
}

interface PageShellProps {
  /** Template class prefix. */
  p: string;
  title: string;
  lead?: string;
  children: React.ReactNode;
}

/** Wrapper giving every generated page the host template's page rhythm. */
function Page({ p, title, lead, children }: PageShellProps) {
  return (
    <section className="mk-page" id="top">
      <div className={`${p}-container`}>
        <header className="mk-page-head">
          <h1 className="mk-page-title">{title}</h1>
          {lead ? <p className="mk-page-lead">{lead}</p> : null}
        </header>
        <div className="mk-page-body">{children}</div>
      </div>
    </section>
  );
}

/* ============================================================
 *  SERVICES
 * ============================================================
 *  The home page lays out three services because that is what
 *  the designs were drawn for. Migrated sites routinely carry
 *  six, nine or twelve. This is the page where all of them
 *  belong, and where the footer's per-service links land.
 * ============================================================ */

export function ServicesPage({ view, p }: PageBodyProps) {
  const services = view.services.filter((s) => s.title);

  return (
    <Page
      p={p}
      title="Our Services"
      lead={view.hasServiceArea ? `What we do, across ${view.serviceArea}.` : undefined}
    >
      <div className="mk-page-services">
        {services.map((service) => (
          <article className="mk-page-service" id={service.slug} key={service.slug}>
            <h2 className="mk-page-service-title">{service.title}</h2>
            {service.description ? (
              <p className="mk-page-service-text">{service.description}</p>
            ) : null}
            {view.hasPhone ? (
              <A className="mk-page-service-cta" href={view.phoneHref}>
                Call about {service.title}
              </A>
            ) : view.hasEmail ? (
              <A className="mk-page-service-cta" href={view.emailHref}>
                Email about {service.title}
              </A>
            ) : null}
          </article>
        ))}
      </div>

      {view.hasPhone || view.hasEmail ? (
        <div className="mk-page-cta">
          <p>Not sure which one you need? Get in touch and we will talk it through.</p>
          {view.hasPhone ? (
            <A className="mk-page-cta-btn" href={view.phoneHref}>
              Call {view.phone}
            </A>
          ) : null}
          {view.hasEmail ? (
            <A className="mk-page-cta-btn" href={view.emailHref}>
              Email us
            </A>
          ) : null}
        </div>
      ) : null}
    </Page>
  );
}

/* ============================================================
 *  PRIVACY
 * ============================================================ */

export function PrivacyPage({ view, p, name }: PageBodyProps) {
  const business = name || 'this business';

  return (
    <Page p={p} title="Privacy Policy" lead={`How this website handles your information.`}>
      <div className="mk-page-prose">
        <p>
          This website is published by {business}. It is an information website: it has no
          accounts to sign up for, no logins, no shopping basket and no payments.
        </p>

        <h2>Information this site collects</h2>
        <p>
          This site does not ask you for personal information and does not set its own cookies.
          There is no analytics or advertising tracking on these pages.
        </p>

        <h2>Information shared with others</h2>
        <p>
          The pages load typefaces from Google Fonts. Loading them sends your IP address and
          browser details to Google, which is how any website using that service works. Some
          photographs may also be loaded from other hosts, which receive the same technical
          details.
        </p>

        <h2>When you contact us</h2>
        <p>
          Calling or emailing the contact details on this site uses your own phone or email
          provider, not this website. Whatever you choose to tell us in that message is what we
          have, and we use it only to answer you and to carry out any work you ask for.
        </p>

        <h2>Your hosting provider</h2>
        <p>
          Like every website, this one is served by a hosting provider that keeps standard server
          logs, which typically include IP addresses and the pages requested.
        </p>

        <h2>Questions</h2>
        <p>
          If you have a question about this policy, or want to know what information we hold about
          you, contact us using the details below.
        </p>
        <ul className="mk-page-contact">
          {view.hasPhone ? (
            <li>
              <A href={view.phoneHref}>{view.phone}</A>
            </li>
          ) : null}
          {view.hasEmail ? (
            <li>
              <A href={view.emailHref}>{view.email}</A>
            </li>
          ) : null}
          {view.hasAddress ? (
            <li>
              <A href={mapHref(view.address)}>{view.address}</A>
            </li>
          ) : null}
        </ul>

        <p className="mk-page-note">
          This policy describes how the website itself works. {business} should have it reviewed
          before publication so that it also covers how the business handles customer information
          away from the site.
        </p>
      </div>
    </Page>
  );
}

/* ============================================================
 *  TERMS
 * ============================================================ */

export function TermsPage({ view, p, name }: PageBodyProps) {
  const business = name || 'this business';

  return (
    <Page p={p} title="Terms of Service" lead="The terms you accept by using this website.">
      <div className="mk-page-prose">
        <p>
          These terms cover your use of this website, which is published by {business}. Using the
          site means you accept them.
        </p>

        <h2>What this site is</h2>
        <p>
          These pages describe the services {business} offers. They are for information. Nothing
          here is a quotation, an offer, or a commitment to carry out work at a particular price
          — a quote is something we give you directly, for your specific job.
        </p>

        <h2>Accuracy</h2>
        <p>
          We keep this site as accurate and current as we reasonably can, but we do not promise it
          is complete or free of errors, and details can change. Check anything you intend to rely
          on with us first.
        </p>

        <h2>Availability</h2>
        <p>
          We do not guarantee the site is available without interruption. It may be unavailable
          during maintenance or for reasons outside our control.
        </p>

        <h2>Content on this site</h2>
        <p>
          The text, images, layout and branding on this site belong to {business} or are used with
          permission. Please do not copy or republish them without asking.
        </p>

        <h2>Links to other sites</h2>
        <p>
          Where this site links somewhere else, we do not control that destination and are not
          responsible for its content.
        </p>

        <h2>Getting in touch</h2>
        <p>Questions about these terms can go to:</p>
        <ul className="mk-page-contact">
          {view.hasPhone ? (
            <li>
              <A href={view.phoneHref}>{view.phone}</A>
            </li>
          ) : null}
          {view.hasEmail ? (
            <li>
              <A href={view.emailHref}>{view.email}</A>
            </li>
          ) : null}
          {view.hasAddress ? (
            <li>
              <A href={mapHref(view.address)}>{view.address}</A>
            </li>
          ) : null}
        </ul>

        <p className="mk-page-note">
          These are general terms for an information website. They deliberately do not state a
          governing law or jurisdiction, because that depends on where {business} trades and is a
          decision for the business, not something this template should assume. Have them reviewed
          before publication.
        </p>
      </div>
    </Page>
  );
}

/** Picks the body for a generated page. */
export function SecondaryPage({
  page,
  ...props
}: PageBodyProps & { page: 'services' | 'privacy' | 'terms' }) {
  if (page === 'services') return <ServicesPage {...props} />;
  if (page === 'privacy') return <PrivacyPage {...props} />;
  return <TermsPage {...props} />;
}
