/**
 * ============================================================
 *  COLOUR ENGINE
 * ============================================================
 *  Takes the 2 brand colours the salesperson types in and
 *  derives a full, accessible palette for light AND dark mode.
 *
 *  IMPORTANT: every value produced here is plain `#rrggbb` or
 *  `rgba()`. No oklch / color-mix / relative colour syntax —
 *  the PNG exporters rasterise the DOM and older colour
 *  functions are the only ones guaranteed to survive that.
 * ============================================================
 */

import type { TemplateId, ThemeMode } from '../types';

export interface Rgb {
  r: number;
  g: number;
  b: number;
}

const HEX_RE = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i;

/** Accepts `abc`, `#abc`, `aabbcc`, `#aabbcc`. Returns `#aabbcc` or null. */
export function normalizeHex(input: string): string | null {
  const value = (input || '').trim();
  if (!HEX_RE.test(value)) return null;
  let hex = value.replace('#', '').toLowerCase();
  if (hex.length === 3) {
    hex = hex
      .split('')
      .map((c) => c + c)
      .join('');
  }
  return `#${hex}`;
}

/** Same as normalizeHex but never fails — falls back to the supplied default. */
export function safeHex(input: string, fallback: string): string {
  return normalizeHex(input) ?? fallback;
}

export function hexToRgb(hex: string): Rgb {
  const normalized = normalizeHex(hex) ?? '#000000';
  return {
    r: parseInt(normalized.slice(1, 3), 16),
    g: parseInt(normalized.slice(3, 5), 16),
    b: parseInt(normalized.slice(5, 7), 16),
  };
}

const toHexPair = (n: number) =>
  Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, '0');

export function rgbToHex({ r, g, b }: Rgb): string {
  return `#${toHexPair(r)}${toHexPair(g)}${toHexPair(b)}`;
}

/** `mix('#ff0000', '#ffffff', 0.25)` → 25% of the way to white. */
export function mix(from: string, to: string, amount: number): string {
  const a = hexToRgb(from);
  const b = hexToRgb(to);
  const t = Math.max(0, Math.min(1, amount));
  return rgbToHex({
    r: a.r + (b.r - a.r) * t,
    g: a.g + (b.g - a.g) * t,
    b: a.b + (b.b - a.b) * t,
  });
}

export const lighten = (hex: string, amount: number) => mix(hex, '#ffffff', amount);
export const darken = (hex: string, amount: number) => mix(hex, '#000000', amount);

/** `rgba()` string from a hex + alpha. */
export function alpha(hex: string, a: number): string {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r}, ${g}, ${b}, ${Math.max(0, Math.min(1, a))})`;
}

/**
 * Rough colourfulness, 0 (grey) → 1 (fully saturated). Used to spot a brand
 * that is too neutral to work as a highlight colour.
 */
export function chroma(hex: string): number {
  const { r, g, b } = hexToRgb(hex);
  return (Math.max(r, g, b) - Math.min(r, g, b)) / 255;
}

/** WCAG relative luminance. */
export function luminance(hex: string): number {
  const { r, g, b } = hexToRgb(hex);
  const channel = (v: number) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
}

/** WCAG contrast ratio between two colours (1 → 21). */
export function contrast(a: string, b: string): number {
  const la = luminance(a);
  const lb = luminance(b);
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

/**
 * Picks near-white or near-black text so it stays readable on `bg`.
 *
 * MTC-MMX-010/013: picking the BETTER of the two is not the same as picking
 * one that passes. A mid-tone brand — the default #1d4ed8 among them — gave
 * a dark ink at 4.35:1, just under AA, on every button and monogram in every
 * template. When neither candidate clears 4.5 the winner is pushed the rest
 * of the way to pure black or pure white, which is the only direction left
 * that does not touch the background colour the design chose.
 */
export function readableOn(bg: string, light = '#ffffff', dark = '#0b1220'): string {
  const best = contrast(bg, light) >= contrast(bg, dark) ? light : dark;
  if (contrast(bg, best) >= 4.5) return best;
  const extreme = best === light ? '#ffffff' : '#000000';
  return contrast(bg, extreme) > contrast(bg, best) ? extreme : best;
}

/**
 * Nudges a brand colour so it stays legible against the page it sits on.
 * Very dark brands get lifted on dark backgrounds; very light brands get
 * deepened on white. Hue is preserved — we only mix toward white/black.
 */
export function toneForSurface(brand: string, surface: string, minRatio = 3.2): string {
  const goingLighter = luminance(surface) < 0.4;
  let out = brand;
  for (let i = 0; i < 14 && contrast(out, surface) < minRatio; i++) {
    out = goingLighter ? lighten(out, 0.08) : darken(out, 0.08);
  }
  return out;
}

// ─────────────────────────────────────────────
//  THEME TOKENS
// ─────────────────────────────────────────────

/**
 * Every token consumed by the template stylesheets. Both templates read the
 * same names, so a template only has to worry about layout — never palette.
 */
export interface ThemeTokens {
  /* brand */
  '--brand': string;
  '--brand-strong': string;
  '--brand-soft': string;
  '--brand-tint': string;
  '--brand-ink': string;
  /** Brand, lifted until it is readable AS TEXT on a light surface. */
  '--brand-on-surface': string;
  /** Brand, lifted until it is readable AS TEXT on the dark panel. */
  '--brand-on-panel': string;
  '--accent': string;
  '--accent-strong': string;
  '--accent-soft': string;
  '--accent-ink': string;
  /** Accent, lifted until it is readable AS TEXT on a light surface. */
  '--accent-on-surface': string;
  /** Accent, lifted until it is readable AS TEXT on the dark panel. */
  '--accent-on-panel': string;
  /* surfaces */
  '--page': string;
  '--surface': string;
  '--surface-2': string;
  '--surface-3': string;
  '--panel': string;
  '--panel-ink': string;
  '--panel-muted': string;
  /* text */
  '--ink': string;
  '--ink-2': string;
  '--ink-3': string;
  /* text sitting on top of a photo */
  '--on-image': string;
  '--on-image-dim': string;
  /** Brand colour lifted until it is legible against the hero overlay. */
  '--on-image-brand': string;
  /** Same treatment for the secondary colour. */
  '--on-image-accent': string;
  /* lines + depth */
  '--line': string;
  '--line-strong': string;
  '--ring': string;
  '--shadow-sm': string;
  '--shadow-md': string;
  '--shadow-lg': string;
  /* overlays */
  '--overlay-ink': string;
  '--hero-overlay': string;
  '--hero-vignette': string;
  '--glass': string;
  '--glass-line': string;
  /* misc */
  '--star': string;
}

export function buildTheme(
  primaryInput: string,
  secondaryInput: string,
  mode: ThemeMode,
  template: TemplateId = 'v3',
): ThemeTokens {
  const primary = safeHex(primaryInput, '#1d4ed8');
  const secondary = safeHex(secondaryInput, '#f97316');
  const isDark = mode === 'dark';

  // v2 ships as a near-black canvas; v3 ships light. In dark mode each one
  // gets the surfaces its own design language expects.
  const darkSurfaces =
    template === 'v2'
      ? { page: '#0b0f14', surface: '#151a21', surface2: '#10151b', surface3: '#1b222b' }
      : { page: '#0b1120', surface: '#131c2e', surface2: '#18233a', surface3: '#1f2c47' };

  const page = isDark ? darkSurfaces.page : '#ffffff';
  const surface = isDark ? darkSurfaces.surface : '#ffffff';
  const surface2 = isDark ? darkSurfaces.surface2 : '#f8f9fa';
  const surface3 = isDark ? darkSurfaces.surface3 : '#eef2f7';

  // Brand tuned so it reads on whichever surface it lands on.
  const brand = toneForSurface(primary, isDark ? surface : '#ffffff', isDark ? 3.6 : 2.6);
  const accent = toneForSurface(secondary, isDark ? surface : '#ffffff', isDark ? 3.6 : 2.6);

  const ink = isDark ? '#f5f8fc' : '#0d1526';
  const ink2 = isDark ? '#c3cddd' : '#3b4a63';
  // MTC-MMX-010: the old light value (#6b7a91) measured 1.76:1 on white,
  // well under AA for the 13px muted text it is used for.
  const ink3 = isDark ? '#8b99b1' : '#55637a';

  // The footer / dark band. In light mode it is an ink-tinted brand black,
  // in dark mode it drops a touch below the page so it still separates.
  const panel = isDark ? '#080e1a' : darken(mix(primary, '#111827', 0.82), 0.1);

  // ── Hero overlay ────────────────────────────────────────────
  // Both source templates lay a NEUTRAL dark over the hero photo
  // (v2: rgba(11,15,20,.82), v3: rgba(11,31,58,.55)). Tinting it
  // heavily with the brand is what turns a photograph into a flat
  // sheet of colour, so the brand is only a hint here — 12% of the
  // mix — and the gradient thins out toward the right so the photo
  // still reads behind the card that sits there.
  // ── MTC-MMX-010: colours that are legible AS TEXT ────────────
  // `--brand` and `--accent` are tuned to be BACKGROUNDS with ink on top.
  // Used directly as a text colour they routinely fail WCAG: a #f97316
  // accent on white measures 2.2:1, and the brand on the dark panel lands
  // near 3:1. These are the same hues lifted until they actually read at
  // small sizes, so a kicker or a badge can carry brand colour honestly.
  const brandOnSurface = toneForSurface(primary, surface, 4.5);
  const accentOnSurface = toneForSurface(secondary, surface, 4.5);
  const brandOnPanel = toneForSurface(primary, panel, 4.5);
  const accentOnPanel = toneForSurface(secondary, panel, 4.5);

  const overlayInk = mix(primary, '#0a0f18', 0.88);
  const liftedBrand = toneForSurface(primary, overlayInk, 4.6);
  const onImageAccent = toneForSurface(secondary, overlayInk, 4.6);

  // Lifting a near-black or near-grey primary far enough to be legible on the
  // photo drains what little colour it had — "Midnight Gold" would headline in
  // grey. In those pairings the secondary is the vivid one, so it takes over
  // the highlight. A brand with real colour of its own always keeps the job.
  const onImageBrand =
    chroma(liftedBrand) < 0.12 && chroma(onImageAccent) > chroma(liftedBrand) + 0.1
      ? onImageAccent
      : liftedBrand;

  return {
    '--brand': brand,
    '--brand-strong': isDark ? lighten(brand, 0.12) : darken(brand, 0.14),
    '--brand-soft': isDark ? alpha(brand, 0.16) : alpha(brand, 0.1),
    '--brand-tint': isDark ? alpha(brand, 0.28) : mix(brand, '#ffffff', 0.9),
    '--brand-ink': readableOn(brand),
    '--brand-on-surface': brandOnSurface,
    '--brand-on-panel': brandOnPanel,
    '--accent': accent,
    '--accent-strong': isDark ? lighten(accent, 0.12) : darken(accent, 0.14),
    '--accent-soft': isDark ? alpha(accent, 0.16) : alpha(accent, 0.1),
    '--accent-ink': readableOn(accent),
    '--accent-on-surface': accentOnSurface,
    '--accent-on-panel': accentOnPanel,

    '--page': page,
    '--surface': surface,
    '--surface-2': surface2,
    '--surface-3': surface3,
    '--panel': panel,
    '--panel-ink': '#ffffff',
    '--panel-muted': isDark ? 'rgba(255,255,255,0.58)' : 'rgba(255,255,255,0.66)',

    '--ink': ink,
    '--ink-2': ink2,
    '--ink-3': ink3,

    '--on-image': '#ffffff',
    '--on-image-dim': 'rgba(255,255,255,0.80)',
    '--on-image-brand': onImageBrand,
    '--on-image-accent': onImageAccent,

    '--line': isDark ? (template === 'v2' ? '#2a2f36' : 'rgba(255,255,255,0.10)') : '#e9ecef',
    '--line-strong': isDark
      ? template === 'v2'
        ? '#363c45'
        : 'rgba(255,255,255,0.18)'
      : '#d3dae4',
    '--ring': isDark ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.9)',

    // Two-stop shadows: a tight contact shadow plus a wide soft one. A single
    // large blur reads as a cheap drop shadow; the pair reads as depth.
    '--shadow-sm': isDark
      ? '0 1px 2px rgba(0,0,0,0.45)'
      : '0 1px 2px rgba(16,24,40,0.04), 0 1px 3px rgba(16,24,40,0.06)',
    '--shadow-md': isDark
      ? '0 2px 6px rgba(0,0,0,0.40), 0 14px 32px rgba(0,0,0,0.45)'
      : '0 2px 4px rgba(16,24,40,0.04), 0 12px 28px rgba(16,24,40,0.08)',
    '--shadow-lg': isDark
      ? '0 6px 14px rgba(0,0,0,0.45), 0 34px 80px rgba(0,0,0,0.60)'
      : '0 4px 8px rgba(16,24,40,0.04), 0 28px 64px rgba(16,24,40,0.16)',

    '--overlay-ink': overlayInk,
    '--hero-overlay': isDark
      ? `linear-gradient(96deg, ${alpha(overlayInk, 0.95)} 0%, ${alpha(overlayInk, 0.88)} 46%, ${alpha(overlayInk, 0.6)} 100%)`
      : `linear-gradient(96deg, ${alpha(overlayInk, 0.92)} 0%, ${alpha(overlayInk, 0.8)} 46%, ${alpha(overlayInk, 0.46)} 100%)`,
    // Darkens the very top and bottom edges so the header and the section
    // seam below both have something to sit against.
    '--hero-vignette': `linear-gradient(180deg, ${alpha(overlayInk, 0.55)} 0%, rgba(0,0,0,0) 22%, rgba(0,0,0,0) 68%, ${alpha(overlayInk, 0.5)} 100%)`,
    '--glass': isDark ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.12)',
    '--glass-line': 'rgba(255,255,255,0.18)',

    '--star': '#fbbf24',
  };
}

/** Turns the token object into an inline `style` object React can apply. */
export function tokensToStyle(tokens: ThemeTokens): React.CSSProperties {
  return tokens as unknown as React.CSSProperties;
}
