/**
 * ============================================================
 *  VIEW MODEL
 * ============================================================
 *  Raw form data is messy — fields get left blank, phone
 *  numbers arrive in five formats, business names are one word
 *  or six. This normalises all of that into something the
 *  templates can render without ever showing a hole.
 * ============================================================
 */

import { NO_IMAGE } from '../types';
import type { MockupData } from '../types';
import { SERVICE_IMAGE_LIBRARY } from './service-images';

export type IconKey =
  | 'roof'
  | 'home'
  | 'hammer'
  | 'paint'
  | 'water'
  | 'tree'
  | 'bolt'
  | 'wrench'
  | 'broom'
  | 'truck'
  | 'shield'
  | 'window'
  | 'fence'
  | 'concrete'
  | 'snow'
  | 'bug'
  | 'car'
  | 'camera'
  | 'tools';

const ICON_RULES: { keys: string[]; icon: IconKey }[] = [
  { keys: ['roof', 'shingle', 'flat roof', 'metal roof'], icon: 'roof' },
  { keys: ['sid', 'stucco', 'exterior', 'render', 'facade'], icon: 'home' },
  { keys: ['gutter', 'drain', 'plumb', 'leak', 'water', 'pipe', 'sewer'], icon: 'water' },
  { keys: ['paint', 'stain', 'coating', 'finish'], icon: 'paint' },
  { keys: ['deck', 'carpent', 'framing', 'trim', 'cabinet', 'remodel', 'wood'], icon: 'hammer' },
  { keys: ['lawn', 'landscap', 'garden', 'tree', 'yard', 'sod', 'irrigation'], icon: 'tree' },
  { keys: ['electric', 'wiring', 'lighting', 'solar', 'panel', 'generator'], icon: 'bolt' },
  { keys: ['hvac', 'heating', 'cooling', 'furnace', 'air condition', 'ac ', 'boiler'], icon: 'wrench' },
  { keys: ['clean', 'janitor', 'maid', 'wash', 'pressure', 'carpet'], icon: 'broom' },
  { keys: ['haul', 'junk', 'moving', 'delivery', 'tow', 'dumpster'], icon: 'truck' },
  { keys: ['window', 'glass', 'door', 'screen'], icon: 'window' },
  { keys: ['fenc', 'gate', 'rail'], icon: 'fence' },
  { keys: ['concrete', 'driveway', 'patio', 'masonry', 'paving', 'asphalt', 'foundation'], icon: 'concrete' },
  { keys: ['snow', 'ice', 'winter', 'plow'], icon: 'snow' },
  { keys: ['pest', 'bug', 'termite', 'rodent', 'exterminat'], icon: 'bug' },
  { keys: ['auto', 'car', 'vehicle', 'detail', 'collision'], icon: 'car' },
  { keys: ['photo', 'video', 'media', 'brand', 'market', 'design'], icon: 'camera' },
  { keys: ['insur', 'secur', 'protect', 'inspect', 'warranty', 'safety'], icon: 'shield' },
  { keys: ['repair', 'maintenance', 'install', 'service', 'restor'], icon: 'tools' },
];

/** Picks a sensible icon from a service name so cards never look generic. */
export function iconForService(title: string, index: number): IconKey {
  const t = (title || '').toLowerCase();
  for (const rule of ICON_RULES) {
    if (rule.keys.some((k) => t.includes(k))) return rule.icon;
  }
  const rotation: IconKey[] = ['tools', 'shield', 'home'];
  return rotation[index % rotation.length];
}

/** Digits-only tel: href, tolerant of `(208) 844-1213`, `+44 1274 723513`, etc. */
export function telHref(phone: string): string {
  const digits = (phone || '').replace(/[^\d+]/g, '');
  return digits ? `tel:${digits}` : '#';
}

/** "4820 W Emerald St, Boise, ID 83706" → "Boise, ID" */
export function shortAddress(address: string): string {
  const parts = (address || '')
    .split(',')
    .map((p) => p.trim())
    .filter(Boolean);
  if (parts.length === 0) return '';
  if (parts.length === 1) return parts[0];
  const city = parts[parts.length - 2];
  const region = parts[parts.length - 1].split(/\s+/)[0];
  return region ? `${city}, ${region}` : city;
}

/**
 * Splits a business name so the header can render it two-tone,
 * exactly like `logoText` + `logoAccent` in the templates.
 */
export function splitName(name: string): { lead: string; accent: string } {
  const words = (name || '').trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return { lead: 'Your', accent: 'Business' };
  if (words.length === 1) {
    const w = words[0];
    if (w.length > 7) {
      const cut = Math.ceil(w.length / 2);
      return { lead: w.slice(0, cut), accent: w.slice(cut) };
    }
    return { lead: w, accent: '' };
  }
  return { lead: words.slice(0, -1).join(' '), accent: words[words.length - 1] };
}

export function initials(name: string): string {
  const words = (name || '').trim().split(/\s+/).filter(Boolean);
  if (!words.length) return 'YB';
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
  return (words[0][0] + words[1][0]).toUpperCase();
}

/**
 * Suggests a card photo from the service name. Returns '' when nothing in the
 * library is a genuine match — the card then renders the branded gradient
 * panel, which beats showing a photo of the wrong trade.
 */
export function imageForService(title: string): string {
  const t = (title || '').toLowerCase();
  if (!t.trim()) return '';
  for (const entry of SERVICE_IMAGE_LIBRARY) {
    if (entry.keys.some((k) => t.includes(k))) return entry.url;
  }
  return '';
}

/** Resolves the stored value ('', 'none' or a URL) to what actually renders. */
export function resolveServiceImage(stored: string | undefined, title: string): string {
  const value = (stored || '').trim();
  if (value === NO_IMAGE) return '';
  if (value) return value;
  return imageForService(title);
}

/**
 * The single town name headlines read best with. Prefers the town out of the
 * address, then the first chunk of the service area, and never falls through
 * to something like "Serving your local area" mid-sentence.
 */
export function pickCity(address: string, serviceArea: string): string {
  const short = shortAddress(address);
  if (short) {
    const town = short.split(',')[0].trim();
    if (town && !/^\d/.test(town)) return town;
  }
  const first = (serviceArea || '').split(/[,&|•]/)[0].trim();
  if (first && first.split(/\s+/).length <= 3 && !/^serving\b/i.test(first)) return first;
  // No address and no usable service area means we do not know the town.
  // Returning a placeholder puts "in Your Area" on a published website.
  return '';
}

/** Trims copy to a headline-friendly length, breaking on a sentence if it can. */
export function clip(text: string, max = 190): string {
  const value = (text || '').trim();
  if (value.length <= max) return value;
  const cut = value.slice(0, max);
  const sentenceEnd = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentenceEnd > max * 0.45) return cut.slice(0, sentenceEnd + 1).trim();
  const space = cut.lastIndexOf(' ');
  return `${cut.slice(0, space > 0 ? space : max).trim()}…`;
}

/** `slugify('Storm & Leak Repair')` → `storm-leak-repair` */
export function slugify(value: string): string {
  return (value || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** Trims a business fact. Returns '' when absent — never a substitute. */
const cleanFact = (value: string | undefined) => (value || '').trim();

const or = (value: string | undefined, fallback: string) =>
  (value || '').trim() ? (value as string).trim() : fallback;

export interface ServiceView {
  title: string;
  description: string;
  icon: IconKey;
  slug: string;
  /** Resolved card photo, or '' to render the branded gradient panel. */
  image: string;
}

export interface MockupView {
  name: string;
  lead: string;
  accent: string;
  initials: string;
  slogan: string;
  /** What the business does, for headline copy. Never '' — see buildView. */
  trade: string;
  phone: string;
  phoneHref: string;
  email: string;
  emailHref: string;
  address: string;
  addressShort: string;
  serviceArea: string;
  /** Single town name, safe to drop straight into a headline. */
  city: string;
  aboutText: string;
  /** Two-sentence version of the about copy, for hero and footer blurbs. */
  aboutShort: string;
  /** Project photos, already filtered to usable URLs. */
  gallery: string[];
  hasGallery: boolean;
  /** A stated trade, else the first slogan segment, else the trade fallback. */
  sloganLead: string;
  services: ServiceView[];
  heroImage: string;
  /** The business's own logo, '' when they have none. */
  logoImage: string;
  hasLogo: boolean;
  hours: string;
  rating: string;
  reviewCount: string;
  years: string;
  credential: string;
  /** Presence flags. Templates must hide an element when its flag is false. */
  hasPhone: boolean;
  hasEmail: boolean;
  hasAddress: boolean;
  hasServiceArea: boolean;
  hasSlogan: boolean;
  hasAbout: boolean;
  hasHours: boolean;
  hasCredential: boolean;
  hasRating: boolean;
  hasReviewCount: boolean;
  hasYears: boolean;
  year: number;
}

const FALLBACK_SERVICES: ServiceView[] = [
  {
    title: 'Service One',
    description: 'Add a short, benefit-led sentence describing this service for the customer.',
    icon: 'tools',
    slug: 'service-one',
    image: '',
  },
  {
    title: 'Service Two',
    description: 'Add a short, benefit-led sentence describing this service for the customer.',
    icon: 'shield',
    slug: 'service-two',
    image: '',
  },
  {
    title: 'Service Three',
    description: 'Add a short, benefit-led sentence describing this service for the customer.',
    icon: 'home',
    slug: 'service-three',
    image: '',
  },
];

export function buildView(data: MockupData): MockupView {
  // Business FACTS are never invented. These templates are not only mockups —
  // they are exported and published as real websites for real companies, so a
  // substituted review score, a "Licensed & Insured" claim or an info@ address
  // nobody owns would be a false statement about someone's business. Absent
  // facts come back empty and the templates hide the element.
  //
  // Only presentational fallbacks survive: a business name so the layout has a
  // logo, and generic service labels so the grid keeps its shape.
  const name = or(data.businessName, 'Your Business Name');
  const { lead, accent } = splitName(name);
  const phone = cleanFact(data.phone);
  const email = cleanFact(data.email);
  const address = cleanFact(data.address);

  const services: ServiceView[] = (data.services || []).slice(0, 3).map((s, i) => {
    const title = or(s?.title, FALLBACK_SERVICES[i]?.title ?? `Service ${i + 1}`);
    return {
      title,
      description: or(s?.description, FALLBACK_SERVICES[i]?.description ?? ''),
      icon: iconForService(title, i),
      slug: slugify(title),
      image: resolveServiceImage(s?.image, title),
    };
  });
  while (services.length < 3) services.push(FALLBACK_SERVICES[services.length]);

  // ── MTC-MMX-009: the headline subject is its own fact ───────────────
  // `setTrade` is what the business actually stated. `trade` is what the
  // templates print. With nothing stated, `trade` reproduces the exact
  // expression the headlines used before this field existed — service slot
  // one — so every existing project, every re-imported JSON and all 32
  // snapshot renders stay byte-for-byte identical.
  //
  // `||` deliberately, not cleanFact alone: cleanFact returns '' for absent,
  // which would blank six headlines. This fallback is legacy compatibility,
  // not an endorsement — it still inherits the invented 'Service One' from
  // FALLBACK_SERVICES when a business names no services at all. Retiring that
  // changes rendered output for existing data, so it is a separate ticket.
  const setTrade = cleanFact(data.trade);
  const trade = setTrade || services[0].title;

  const serviceArea = cleanFact(data.serviceArea);
  const slogan = cleanFact(data.slogan);
  const sloganFirst = slogan.split(/[•|,]/)[0].trim();
  const aboutText = cleanFact(data.aboutText);
  const credential = cleanFact(data.credential);
  const rating = cleanFact(data.reviewRating);
  const reviewCount = cleanFact(data.reviewCount);
  const years = cleanFact(data.yearsInBusiness);
  const hours = cleanFact(data.hours);
  // Only real URLs; a blank entry would render an empty tile.
  const gallery = (data.gallery || []).map((url) => (url || '').trim()).filter(Boolean);

  return {
    name,
    lead,
    accent,
    initials: initials(name),
    slogan,
    trade,
    // A stated trade outranks the slogan heuristic. Without the `setTrade ||`
    // prefix a rep who fills in the trade gets "Expert Roofing Across Boise"
    // in one template and "Roofing • Siding Done Right" in another — one
    // dataset making two different claims about what the company is. With the
    // trade unset this is character-for-character the old expression, because
    // `trade` is then exactly `services[0].title`.
    sloganLead:
      setTrade || (sloganFirst && sloganFirst.length <= 30 ? sloganFirst : trade),
    phone,
    // '' rather than '#': <A> renders an inert element for an empty href,
    // so a business with no phone never ships a link to nowhere.
    phoneHref: phone ? telHref(phone) : '',
    email,
    emailHref: email ? `mailto:${email}` : '',
    address,
    addressShort: address ? shortAddress(address) : '',
    serviceArea,
    city: pickCity(address, serviceArea),
    aboutText,
    aboutShort: aboutText ? clip(aboutText, 190) : '',
    services,
    // No stock fallback. An empty hero renders the branded gradient, which is
    // honest; substituting a photo of another trade is not. Migrated legacy
    // sites carry no image URLs at all, and a roofer on a painter's website is
    // worse than no photograph.
    heroImage: (data.heroImage || '').trim(),
    // A logo is the business's own mark. Absent means absent — the
    // templates fall back to a monogram built from their name.
    logoImage: (data.logoImage || '').trim(),
    hasLogo: Boolean((data.logoImage || '').trim()),
    gallery,

    hours,
    rating,
    reviewCount,
    years,
    credential,
    hasPhone: Boolean(phone),
    hasEmail: Boolean(email),
    hasAddress: Boolean(address),
    hasServiceArea: Boolean(serviceArea),
    hasSlogan: Boolean(slogan),
    hasAbout: Boolean(aboutText),
    hasHours: Boolean(hours),
    hasCredential: Boolean(credential),
    hasRating: Boolean(rating),
    hasReviewCount: Boolean(reviewCount),
    hasYears: Boolean(years),
    hasGallery: gallery.length > 0,
    year: new Date().getFullYear(),
  };
}
